export const ifcViewerCardSchema = z.object({ "highlights": z.union([z.array(z.any()), z.null()]).describe("Element groups to colour in the viewer, each with a verdict").default(null), "model_file": z.union([z.string(), z.null()]).describe("File name of the model, exactly as ifc_query reported it (e.g. 'haus-a.ifc'). Leave empty when the project has only one model.").default(null), "note": z.union([z.string(), z.null()]).describe("Optional one-line clarification under the viewer").default(null), "storey": z.union([z.string(), z.null()]).describe("Storey name to isolate on open, e.g. 'Erdgeschoss'").default(null), "title": z.string().min(1).describe("Short heading, e.g. 'Brandabschnitte – EG'"), "type": z.literal("ifc_viewer") }).describe("The project's IFC model, rendered in 3D, with findings highlighted on it.\n\nUse when the answer is ABOUT specific parts of the building and seeing them\nbeats reading their names — a compliance finding on particular walls, the\nrooms that fall below a required area, the escape route being discussed.\nDo NOT use it as a decorative \"here is your building\": an unhighlighted\nviewer says nothing a sentence does not.")

export const ifcComplianceCardSchema = z.object({ "model_file": z.union([z.string(), z.null()]).describe("File name of the model as ifc_query reported it. Empty when the project has one model.").default(null), "note": z.union([z.string(), z.null()]).describe("Optional one-line clarification").default(null), "rule_ids": z.array(z.string()).max(20).describe("Rule ids from ifc_query operation='compliance' (e.g. 'oib2-feuerwiderstand-tragend') to narrow the card to the requirements this answer is about. Empty shows all. Use ONLY ids the tool reported; the card says so when one does not resolve.").optional(), "title": z.string().min(1).describe("Short heading, e.g. 'Anforderungen Brandschutz'"), "type": z.literal("ifc_compliance") }).describe("The Prüfbuch: OIB requirements with their verdict against this model.\n\nCarries only WHICH requirements to show; the frontend runs the catalogue and\nrenders the counts, the thresholds and the failing elements itself. The\nmodel therefore cannot state that a building complies, because it never\nsupplies a verdict — the same reason the schedule card carries no areas.\n\nUse when the user asks whether the model meets a requirement, what is still\nopen, or what they have to add to the model. Prefer it over prose whenever\nthe answer is a list of requirements: the card stays correct after the model\nchanges, and a sentence does not.\n\nNEVER present this as a Nachweis. The catalogue reads only published\nproperty values, it reads no geometry, and Fluchtweglängen, Geländerhöhen\nand Brandabschnittsgrößen are not in it at all.")

export const ifcScheduleCardSchema = z.object({ "model_file": z.union([z.string(), z.null()]).describe("File name of the model as ifc_query reported it. Empty when the project has one model.").default(null), "note": z.union([z.string(), z.null()]).describe("Optional one-line clarification").default(null), "storey": z.union([z.string(), z.null()]).describe("Limit the table to one storey, e.g. 'Erdgeschoss'. Empty shows all.").default(null), "title": z.string().min(1).describe("Short heading, e.g. 'Flächenaufstellung'"), "type": z.literal("ifc_schedule") }).describe("The project's Raumbuch (room schedule) straight from the model.\n\nThe card names WHICH table to show; the frontend fetches the numbers from\nthe model itself. The model therefore cannot get an area wrong, because it\nnever supplies one — the same reason the viewer card carries GlobalIds and\nnot geometry.\n\nUse when the user asks for room areas, a Flächenaufstellung, or \"what rooms\nare on the second floor\".")

export const ifcElementCardSchema = z.object({ "global_id": z.string().min(1).describe("IFC GlobalId returned by ifc_query. NEVER invent one — an id you did not see resolves to nothing."), "model_file": z.union([z.string(), z.null()]).describe("Model file name; empty when there is one model.").default(null), "note": z.union([z.string(), z.null()]).describe("Why this element matters to the answer").default(null), "title": z.string().min(1).describe("Short heading, e.g. 'Aussenwand Nord'"), "type": z.literal("ifc_element") }).describe("One element of the model, in full, with a link into the 3D view.\n\nUse when the answer is ABOUT a specific element the user will want to look\nat — the wall that fails a requirement, the door being discussed. The card\ncarries only the GlobalId; every property shown is read live from the model.")

