export const calculationLimitSchema = z.object({ "comparator": z.enum(["<=",">=","between"]).describe("How the result must relate to the bound: at most, at least, or inside a range"), "label": z.union([z.string(), z.null()]).describe("Optional name of the limit, e.g. 'Schrittmaßregel'; omit when the reference says it").default(null), "reference": z.union([z.any(), z.null()]).describe("Where the bound is written. Never invent one").default(null), "upper": z.union([z.number(), z.null()]).describe("With 'between': the upper bound, e.g. 65 for the Schrittmaßregel's 59–65 cm. Otherwise omit").default(null), "value": z.number().describe("The bound. With 'between', this is the LOWER bound") }).describe("The Bestimmung the derived result is held against.\n\nThe comparator and the bound are the model's to supply — they are read out\nof the Richtlinie. The VERDICT is not: the renderer compares its own\ncomputed result against this and colours the card accordingly, so a card\ncannot show a green tick above arithmetic that fails.")

export const calculationOperandSchema = z.object({ "factor": z.union([z.number(), z.null()]).describe("Only on a 'sum': the RULE's own multiplier for this term, e.g. 2 in the Schrittmaßregel '2 × Steigung + Auftritt'. Negative subtracts the term. Omit for a plain +1 — never use it to smuggle a second measured quantity in, which is what a 'product' step is for").default(null), "label": z.string().describe("What this number IS, e.g. 'Steigung', 'Bruttogeschossfläche', 'Grundfläche'. Empty ONLY for a bare constant that names itself, such as the 1 in a U-value's 1 ÷ R — everything a reader has to look up needs its name under it"), "provenance": z.union([z.enum(["declared","computed","inferred"]), z.null()]).describe("Where `value` came from, copied from the ifc_measure answer's own provenance: 'declared' (the IFC file states it), 'computed' (we measured it off the geometry), 'inferred' (a heuristic). Leave null for a figure the user typed or a limit read out of the Bestimmung. NEVER guess it").default(null), "source": z.union([z.string(), z.null()]).describe("Optional half-line naming WHERE the figure is written down, e.g. 'Einreichplan, Schnitt A-A' or 'Bebauungsplan PD 8123'. Revealed when the reader expands the derivation's sources").default(null), "step": z.union([z.number().int(), z.null()]).describe("Instead of a value: the 1-based index of an EARLIER step whose result this operand is. Must point strictly backwards. With this set, leave value, unit, provenance and tolerance null — the renderer takes them from the step it names").default(null), "tolerance": z.union([z.number().gte(0), z.null()]).describe("The ± band on `value`, in the SAME unit — copied from the ifc_measure answer, and only meaningful with provenance 'computed'. The renderer propagates it through every following step, so this is what decides whether the derived result is genuinely on one side of a limit").default(null), "unit": z.union([z.string(), z.null()]).describe("Unit of this operand, e.g. 'cm', 'm²', 'MJ'; omit for a bare count or a ratio").default(null), "value": z.union([z.number(), z.null()]).describe("The number itself. Leave null when it is not known — the renderer then shows the step as undecidable instead of a result, which is the honest outcome. Must be null when `step` is set").default(null) }).describe("One number entering a step of the derivation, with where it came from.\n\nEither a literal ``value`` or a reference to an earlier ``step`` — never\nboth, because a stated value beside a reference is two answers to the same\nquestion and the renderer would have to pick one.\n\nCarries the same provenance vocabulary as :class:`DimensionCheck`, for the\nsame reason: a derived number is only as honest as its inputs, and a\nSchrittmaß computed from a measurement of ours is our claim, not the\narchitect's. The renderer propagates every band it is given into the result,\nso a tolerance dropped here is a tolerance dropped from the answer.")

export const calculationStepSchema = z.object({ "label": z.string().min(1).describe("What this step computes, e.g. 'Schrittmaß', 'Geschossflächenzahl'"), "operands": z.array(z.any()).min(2).max(6).describe("The numbers going in, in the order they are read. 'quotient', 'percent_of' and 'percent_ratio' take EXACTLY two"), "operation": z.enum(["sum","product","quotient","percent_of","percent_ratio"]).describe("Which of the five shapes this step is: 'sum' (Σ factor × value), 'product' (Π value), 'quotient' (first ÷ second), 'percent_of' (second, as a percentage, OF first), 'percent_ratio' (first ÷ second × 100, a percentage)"), "unit": z.union([z.string(), z.null()]).describe("Unit of THIS step's result, e.g. 'cm', 'm²', 'W/(m²K)'; omit for a dimensionless ratio like a GFZ. Ignored on 'percent_ratio', whose result is always a percentage").default(null) }).describe("One line of the Rechenweg: an operation over its operands.\n\nThe step states no result. The renderer evaluates ``operation`` over\n``operands`` and prints what it computed — which is the whole point of the\ncard, so there is no field here for the model to disagree with it in.")

