export const dimensionCheckSchema = z.object({ "comparator": z.union([z.enum(["<=",">="]), z.null()]).describe("How actual must relate to required").default(null), "label": z.string().min(1).describe("What is measured, e.g. 'lichte Durchgangsbreite'"), "missing": z.union([z.string(), z.null()]).describe("With status 'needs_input': what the export does not provide and WHAT TO CHANGE IN THE CAD to make it answerable — copied verbatim from the ifc_measure answer's missing.remedy. This is the sentence the architect acts on, and a card that shows an empty slot instead of it turns a finding about the export into a blank the reader reads as a fact about the building.").default(null), "provenance": z.union([z.enum(["declared","computed","inferred"]), z.null()]).describe("Where `value` came from, copied from the ifc_measure answer's own provenance: 'declared' (the IFC file states it), 'computed' (we measured it off the geometry), 'inferred' (a heuristic, offered for confirmation). Leave null when the number did not come from the model at all — a figure the user typed, or one taken from the Bestimmung. NEVER guess it: labelling our own measurement 'declared' turns our tolerance into the architect's claim.").default(null), "required": z.union([z.number(), z.null()]).describe("OIB limit for this dimension").default(null), "status": z.enum(["pass","fail","warning","needs_input"]).describe("Verdict for this dimension"), "tolerance": z.union([z.number().gte(0), z.null()]).describe("The ± band on `value`, in the SAME unit — copied from the ifc_measure answer. Only meaningful with provenance 'computed': a declared figure is the file's statement and has no band of ours. A measured dimension without its band reads as exact, and the band is what decides whether 2.49 m clears a 2.50 m minimum.").default(null), "unit": z.string().describe("Unit for both value and required, e.g. 'cm', 'm', '%'").default("cm"), "value": z.union([z.number(), z.null()]).describe("Actual measurement (drawn); null if unknown").default(null) }).describe("One measured dimension drawn on a schematic and checked against a limit.\n\n`value` is the project's actual measurement (drawn to scale); `required` is\nthe OIB limit. If `value` is unknown, leave it null and set status\n'needs_input'.\n\n## Why a number here carries where it came from\n\nThis block used to be `label / value / required / unit / comparator /\nstatus` and nothing else, and that made the card the least honest surface in\nthe product. `ifc_measure` answers „gemessen: 2.47 m (±5 mm) — aus der\nGeometrie berechnet, nicht deklariert\", the assistant repeats that in the\nprose, and the card beside it drew **2.47 m ✓** — indistinguishable from a\nfigure the architect had stated in their own file. The card is the part a\nreviewer screenshots into a submission, so the surface that dropped the\nqualifier was the surface most likely to be forwarded without it.\n\nThree fields close that, and all three are OPTIONAL: a card built from the\nBestimmung alone (a limit with no model behind it) has nothing to put in\nthem, and a null here means \"not stated\", never \"declared\".")

