export const followUpSchema = z.object({ "hint": z.union([z.string(), z.null()]).describe("Optional half-line saying what asking this would get the reader, e.g. 'Messpunkt und Bezugsebene'. Shown only as a tooltip — never the question itself, and omit it rather than restating the question in other words").default(null), "question": z.string().min(1).describe("The next question as a COMPLETE, sendable sentence in the answer's language — this exact text lands in the composer, so 'Wie wird das Fluchtniveau gemessen?' works and a topic label like 'Fluchtniveau' does not. Name something this answer introduced: a term it defined, a value it gave, a caveat it raised") }).describe("One next question, written out in full so it can be sent as it stands.")

export const ifcElementMatchSchema = z.object({ "classification": z.union([z.string(), z.null()]).describe("Case-insensitive substring of a classification code or label").default(null), "ifc_types": z.union([z.array(z.string()), z.null()]).describe("Canonical IFC types, e.g. ['IfcWall']").default(null), "material": z.union([z.string(), z.null()]).describe("Case-insensitive substring of a material name").default(null), "name_contains": z.union([z.string(), z.null()]).describe("Case-insensitive substring of the element name").default(null), "properties": z.union([z.array(z.any()), z.null()]).describe("Property predicates, all required").default(null), "storeys": z.union([z.array(z.string()), z.null()]).describe("Storey names, e.g. ['Erdgeschoss']").default(null) }).describe("The SET of elements to highlight, as a filter rather than a list of ids.\n\nExactly the ``filters`` object passed to ``ifc_query`` — the browser re-runs\nit against the model, so the highlight covers every matching element and\nnothing has to survive the model's context window.\n\n``ifc_query`` spells its filter keys in camelCase (``ifcTypes``,\n``nameContains``) and this card is authored in snake_case like every other\ncard field. The agent is told to reuse the filter it already wrote, so BOTH\nspellings are accepted and normalise to the snake_case field: without the\naliases a copied filter validated cleanly with every key silently dropped,\nleaving an empty match, and a highlight group that selects nothing.")

export const ifcHighlightSchema = z.object({ "global_ids": z.union([z.array(z.string()).min(1), z.null()]).describe("IFC GlobalIds returned by ifc_query OR by ifc_measure. NEVER invent these — an id you did not see is a wrong answer. Use for a handful of elements the answer names; use 'match' for a set. When the answer came from a MEASUREMENT, the ids to highlight are the ones the measurement itself names: every ifc_measure answer ends with a 'Bezug:' line listing exactly the elements the number was derived from, and highlighting those shows the user the thing that was measured rather than a description of it.").default(null), "label": z.string().min(1).describe("What is being shown, e.g. 'Fluchtweg > 40 m'"), "match": z.union([z.any(), z.null()]).describe("The ifc_query filter that selects this set. Preferred over global_ids for anything larger than a few elements — reuse the exact filters you queried with.").default(null), "status": z.enum(["pass","fail","warning","info"]).describe("Verdict colour: pass=green, fail=red, warning=amber, info=neutral").default("info") }).describe("One set of model elements to call out, with a verdict.\n\nEXACTLY ONE of ``match`` or ``global_ids`` — never both, never neither.\n(Stated here because the rendered card catalogue lists a model's fields\nfrom ``model_fields`` and never sees a ``model_validator``: both selectors\ntherefore appear as plain optionals, and the worked example — one group of\neach kind — reads as permission to supply both. A highlight that does is\ndropped, taking its whole card with it.)\n\nPrefer ``match`` whenever the\nanswer is about a set rather than about elements you named. An id list has\nto travel through the model's context, so \"the 420 external walls\" arrived\nas whatever fitted and the card highlighted a fraction of the answer while\nthe legend claimed all of it. A filter is re-run in the browser: the whole\nset lights up, and it costs the model a filter it has already written.")

export const ifcPropertyMatchSchema = z.object({ "name": z.string().min(1).describe("Property name, e.g. 'IsExternal' or 'FireRating'"), "operator": z.enum(["eq","neq","contains","gt","gte","lt","lte","exists","missing"]).describe("Comparison. 'exists'/'missing' take no value.").default("eq"), "set": z.union([z.string(), z.null()]).describe("Property-set name, e.g. 'Pset_WallCommon'. Omit to search every set.").default(null), "source": z.enum(["property","quantity"]).describe("Which store to search: 'property' (default) or 'quantity'").default("property"), "value": z.union([z.string(), z.number(), z.boolean(), z.null()]).describe("Value to compare against").default(null) }).describe("One property predicate, in ifc_query's own filter grammar.")

export const keyTakeawaySchema = z.object({ "detail": z.union([z.string(), z.null()]).describe("One or two sentences revealed when the reader expands this takeaway — the derivation, the caveat or the exception behind it. Never a restatement of `text`; omit if there is nothing to add").default(null), "text": z.string().min(1).describe("The takeaway as ONE scannable line, e.g. 'Fluchtniveau 9,80 m → Gebäudeklasse 4'") }).describe("One takeaway: the line the reader leaves with, plus the detail behind it.")

export const normChainLinkSchema = z.object({ "label": z.string().min(1).describe("The norm's name, e.g. 'OIB-Richtlinie 2', 'ÖNORM B 1600'"), "note": z.union([z.string(), z.null()]).describe("What this link contributes to the chain, e.g. 'verweist auf die ÖNORM B 1600'").default(null), "rank": z.enum(["bundesgesetz","landesgesetz","verordnung","oib_richtlinie","oenorm","leitfaden"]).describe("The link's classification for display: 'bundesgesetz', 'landesgesetz' and 'verordnung' bind; 'oib_richtlinie' binds where a Land has declared it; 'oenorm' and 'leitfaden' interpret. Drives the binding-vs-interpretive weight in the render — the agent's own classification, not a lookup") }).describe("One link in a norm hierarchy, with the rank that sets its visual weight.")

export const normReferenceSchema = z.object({ "document": z.string().min(1).describe("Regulation name, e.g. 'OIB-Richtlinie 2', 'ÖNORM B 1600'"), "edition": z.union([z.string(), z.null()]).describe("Edition/year, e.g. 'Ausgabe Mai 2023'").default(null), "excerpt": z.union([z.string(), z.null()]).describe("Literal quoted sentence grounding the value (<= ~200 chars)").default(null), "section": z.union([z.string(), z.null()]).describe("Clause/table, e.g. 'Pkt. 5.1.1', 'Tabelle 1b'").default(null) }).describe("A verifiable pointer into a regulation (the atom of grounding).\n\nEvery required value MUST carry one so the architect can verify it against\nthe source. Never fabricate a reference.")

export const obstructionSchema = z.object({ "distance_m": z.number().gt(0).describe("Horizontal distance from the window in metres"), "height_m": z.number().describe("Height of the obstruction above the window sill in metres"), "label": z.string().min(1).describe("What it is, e.g. 'Gegenüberliegendes Gebäude'") }).describe("An object blocking daylight (opposing building, own projection).")

export const processStepSchema = z.object({ "actor": z.union([z.string(), z.null()]).describe("Who acts at this step, e.g. 'Bauwerber', 'Baubehörde', 'Ziviltechniker'").default(null), "duration": z.union([z.string(), z.null()]).describe("How long the step runs or the Frist attached to it, AS WRITTEN — 'binnen sechs Wochen', '8 Wochen ab Einreichung'. Never a date: nothing here is calculated, and a computed deadline would be a legal statement about this project that the card cannot make").default(null), "label": z.string().min(1).describe("The step's name, e.g. 'Einreichung', 'Bauverhandlung'"), "produces": z.array(z.string()).describe("What comes out of it, e.g. 'Baubewilligungsbescheid', 'Verhandlungsschrift'").optional(), "reference": z.union([z.any(), z.null()]).describe("The Bestimmung governing this step, e.g. the Bauordnung paragraph. Never invent one").default(null), "requires": z.array(z.string()).describe("What must be in hand for this step, e.g. 'Einreichplan', 'Baubeschreibung', 'Energieausweis'").optional(), "summary": z.union([z.string(), z.null()]).describe("One short line saying what happens here — shown in the row, so keep it to a clause").default(null) }).describe("One station of a Verfahren, with what it needs and what it produces.")

export const projectProfilePatchOperationSchema = z.object({ "op": z.enum(["add","replace","remove"]), "path": z.string().describe("For a confirmed hard fact use \"/facts/<key>\" with op \"add\" (works for both new and changed values). For an uncertain inference use \"/assumptions/<key>\". Known fact keys and values: hauptnutzung: wohnen|buero|beherbergung|versammlung|gesundheit|landwirtschaft|produzierend|lager|sonstiges; gebaeudeklasse: GK1|GK2|GK3|GK4|GK5; fluchtniveau: <=7m|7-11m|11-22m|>22m; bestand_neubau: bestand|neubau|zu_und_umbau; widmung: bauland|verkehrsflaeche|freiland|kerngebiet|gemischt; bauweise: offen|gekuppelt|geschlossen; sicherheitskategorie: low|medium|high; bestandsalter: <10|10-30|30-50|>50; geschosse_oberirdisch / geschosse_unterirdisch / anzahl_betten / anzahl_einheiten: number; grundgrenze / fluchtlinie / schutzzone / abweichender_bebauungsplan: boolean; hohe_gebaeude_details: free text"), "value": z.any().describe("The PLAIN value only (e.g. \"GK4\", 3, true) — never wrap it in an object; the app adds provenance metadata when the user accepts.").default(null) }).describe("A JSON Patch operation targeting a project profile section.")

export const projectProfilePatchPreviewItemSchema = z.object({ "after": z.string(), "before": z.string(), "label": z.string() }).describe("A before/after preview for a single patched field.")

export const sectionMarkerSchema = z.object({ "height_m": z.number().describe("Height above ground datum in metres"), "kind": z.enum(["fluchtniveau","threshold","reference"]).describe("Styling role").default("reference"), "label": z.string().min(1).describe("What the line marks, e.g. 'Fluchtniveau', 'GK4-Grenze'") }).describe("A horizontal reference line at a given height in the section.")

export const sectionStoreySchema = z.object({ "below_grade": z.boolean().describe("True for basements/underground storeys").default(false), "height_m": z.number().gt(0).describe("Clear storey height in metres (drawn to scale)"), "label": z.string().min(1).describe("Storey label, e.g. 'EG', '1.OG', 'KG'") }).describe("One storey in a building cross-section, drawn as a band to scale.")

export const setbackSideSchema = z.object({ "actual_m": z.union([z.number(), z.null()]).describe("Actual distance in metres; null if unknown").default(null), "required_m": z.number().describe("Required setback in metres (OIB/Bauordnung)"), "side": z.enum(["front","back","left","right"]).describe("Which edge"), "status": z.enum(["pass","fail","warning","needs_input"]).describe("Verdict for this side") }).describe("A required distance from the building footprint to one parcel edge.")

export const surfacedDocumentSchema = z.object({ "file_name": z.string().min(1).describe("Exact indexed file name (resolves to the live document row)"), "page": z.union([z.number().int(), z.null()]).describe("1-based page the snippet came from, if known").default(null), "score": z.union([z.number(), z.null()]).describe("0..1 relevance score of the best chunk").default(null), "snippet": z.union([z.string(), z.null()]).describe("Best-matching passage — WHY this file surfaced").default(null), "source": z.union([z.enum(["projekt","buero"]), z.null()]).describe("Which corpus it came from: 'projekt' (project) or 'buero' (Büroarchiv)").default(null), "summary": z.union([z.string(), z.null()]).describe("One-line description of what the document is").default(null) }).describe("One real document surfaced by a corpus search, with its match evidence.")

export const typedColumnSchema = z.object({ "label": z.string().min(1).describe("Column header, e.g. 'Bauteil', 'Mindestmaß'"), "type": z.enum(["mass","norm","verdict","date","text"]).describe("How the frontend renders this column's cells: 'mass' (a dimension — right-aligned, tabular-nums), 'date' (right-aligned, tabular-nums), 'verdict' (a pass/fail-style status — a chip), 'norm' (a norm reference — emphasised), or 'text' (plain left-aligned prose)") }).describe("One column of a typed table, declaring how its cells are rendered.")

